65	const CandidateDetailSheet = ({
66	  result: r,
67	  isOpen,
68	  onClose,
69	  jobId,
70	  jobTitle,
71	  teamId,
72	  formatCandidateName,
73	  onDownload,
74	  onDismiss,
75	  currentStage,
76	  stageUpdatedAt,
77	  onStageChange,
78	  tags = [],
79	  teamMembers = [],
